107: int32_t DBinderServiceStub::ProcessProto(uint32_t code, MessageParcel &data, MessageParcel &reply,
108:     MessageOption &option)
109: {
110:     sptr<DBinderService> dBinderService = DBinderService::GetInstance();
111:     if (dBinderService == nullptr) {
112:         DBINDER_LOGE(LOG_LABEL, "DBinderService is nullptr");
113:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_GET_SERVICE_NULL, __FUNCTION__);
114:         return DBINDER_SERVICE_PROCESS_PROTO_ERR;
115:     }
116:     auto session = dBinderService->QuerySessionObject(reinterpret_cast<binder_uintptr_t>(this));
117:     if (session == nullptr) {
118:         DBINDER_LOGE(LOG_LABEL, "client find session is null");
119:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_QUERY_SESSION_FAIL, __FUNCTION__);
120:         return DBINDER_SERVICE_PROCESS_PROTO_ERR;
121:     }
122: 
123:     DBINDER_LOGI(LOG_LABEL, "serviceName:%{public}s stubIndex:%{public}" PRIu64 " tokenId:%{public}u",
124:         session->serviceName.c_str(), session->stubIndex, session->deviceIdInfo.tokenId);
125: 
126:     int uid = IPCSkeleton::GetCallingUid();
127:     int pid = IPCSkeleton::GetCallingPid();
128:     if (uid < 0 || pid < 0) {
129:         DBINDER_LOGE(LOG_LABEL, "uid or pid err");
130:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_GET_UID_OR_PID_FAIL, __FUNCTION__);
131:         return DBINDER_SERVICE_PROCESS_PROTO_ERR;
132:     }
133: 
134:     std::string localBusName = dBinderService->CreateDatabusName(uid, pid);
135:     if (localBusName.empty()) {
136:         DBINDER_LOGE(LOG_LABEL, "local busname nil");
137:         DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_CREATE_BUS_NAME_FAIL, __FUNCTION__);
138:         return DBINDER_SERVICE_PROCESS_PROTO_ERR;
139:     }
140: 
141:     switch (session->type) {
142:         case IRemoteObject::DATABUS_TYPE: {
143:             if (!reply.WriteUint32(IRemoteObject::IF_PROT_DATABUS) || !reply.WriteUint64(session->stubIndex) ||
144:                 !reply.WriteString(session->serviceName) || !reply.WriteString(session->deviceIdInfo.toDeviceId) ||
145:                 !reply.WriteString(session->deviceIdInfo.fromDeviceId) || !reply.WriteString(localBusName) ||
146:                 !reply.WriteUint32(session->deviceIdInfo.tokenId) || !reply.WriteString16(descriptor_)) {
147:                 DBINDER_LOGE(LOG_LABEL, "write to parcel fail");
148:                 DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_WRITE_TO_PARCEL_FAIL, __FUNCTION__);
149:                 return DBINDER_SERVICE_PROCESS_PROTO_ERR;
150:             }
151:             break;
152:         }
153:         default: {
154:             DBINDER_LOGE(LOG_LABEL, "Invalid Type");
155:             DfxReportFailEvent(DbinderErrorCode::RPC_DRIVER, RADAR_TYPE_INVALID, __FUNCTION__);
156:             return DBINDER_SERVICE_PROCESS_PROTO_ERR;
157:         }
158:     }
159:     return ERR_NONE;
160: }

162: int32_t DBinderServiceStub::OnRemoteRequest(uint32_t code, MessageParcel &data, MessageParcel &reply,
163:     MessageOption &option)
164: {
165:     int32_t result = ERR_NONE;
166:     switch (code) {
167:         case GET_PROTO_INFO: {
168:             result = ProcessProto(code, data, reply, option);
169:             break;
170:         }
171:         case DBINDER_OBITUARY_TRANSACTION: {
172:             result = ProcessDeathRecipient(data);
173:             break;
174:         }
175:         default: {
176:             DBINDER_LOGI(LOG_LABEL, "unknown code:%{public}u", code);
177:             result = DBINDER_SERVICE_UNKNOW_TRANS_ERR;
178:             break;
179:         }
180:     }
181: 
182:     return result;

198: ::ohos::rpc::rpc::OnRemoteMessageRequestResultUnion ANIRemoteObject::callOnRemoteMessageRequest(int32_t code,
199:     ::ohos::rpc::rpc::weak::MessageSequence data, ::ohos::rpc::rpc::weak::MessageSequence reply,
200:     ::ohos::rpc::rpc::weak::MessageOption options)
201: {
202:     if (!jsObjRef_.has_value()) {
203:         ZLOGE(LOG_LABEL, "jsObjRef_ is empty");
204:         return ::ohos::rpc::rpc::OnRemoteMessageRequestResultUnion::make_booleanValue(false);
205:     }
206:     auto jsObjRef = jsObjRef_.value();
207: 
208:     if (hasCallingInfoAni_) {
209:         ::ohos::rpc::rpc::OnRemoteMessageRequestResultUnion retWithCallingInfo =
210:             jsObjRef->OnRemoteMessageRequestWithCallingInfo(code, data, reply, options, GetCallingInfo());
211:         return retWithCallingInfo;
212:     } else {
213:         ::ohos::rpc::rpc::OnRemoteMessageRequestResultUnion ret =
214:             jsObjRef->OnRemoteMessageRequest(code, data, reply, options);
215:         return ret;
216:     }
217: }

219: int ANIRemoteObject::OnRemoteRequest(uint32_t code, OHOS::MessageParcel &data, OHOS::MessageParcel &reply,
220:     OHOS::MessageOption &option)
221: {
222:     auto [asyncCallback, future] =
223:         ::taihe::make_async_pair<::taihe::expected<::ohos::rpc::rpc::RequestResult, ::taihe::error>>();
224:     auto jsData = taihe::make_holder<MessageSequenceImpl, ::ohos::rpc::rpc::MessageSequence>(&data);
225:     jsData->AddJsObjWeakRef(jsData);
226:     auto jsReply = taihe::make_holder<MessageSequenceImpl, ::ohos::rpc::rpc::MessageSequence>(&reply);
227:     jsReply->AddJsObjWeakRef(jsReply);
228:     auto jsOption = taihe::make_holder<MessageOptionImpl, ::ohos::rpc::rpc::MessageOption>(option.GetFlags(),
229:         option.GetWaitTime());
230:     ::ohos::rpc::rpc::OnRemoteMessageRequestResultUnion res =
231:         callOnRemoteMessageRequest(code, jsData, jsReply, jsOption);
232:     if (res.holds_booleanValue()) {
233:         bool boolRes = res.get_booleanValue_ref();
234:         return boolRes ? OHOS::ERR_NONE : OHOS::ERR_UNKNOWN_TRANSACTION;
235:     } else {
236:         res.get_promiseValue_ref().on_complete(
237:             [cb = std::move(asyncCallback), code, jsData = ::ohos::rpc::rpc::MessageSequence(jsData), jsReply =
238:             ::ohos::rpc::rpc::MessageSequence(jsReply)](::taihe::expected<bool, ::taihe::error> expectedBool) {
239:             if (expectedBool.has_value()) {
240:                 int32_t retVal = expectedBool.value() ? OHOS::ERR_NONE : OHOS::ERR_UNKNOWN_TRANSACTION;
241:                 ::ohos::rpc::rpc::RequestResult resRequestResult = { retVal, code, jsData, jsReply };
242:                 cb.complete(resRequestResult);
243:             } else {
244:                 cb.complete(::taihe::unexpected<taihe::error>(expectedBool.error()));
245:             }
246:         });
247:         return OHOS::ERR_NONE;
248:     }
249: }
